INSERT INTO roles (id, silo_id, title, description, qualities, selection_order, proximity_score, created_at)
VALUES
  ('01d5fdd1-633c-4663-9833-b2f5990cb5d4', '11111111-0000-0000-0000-000000000005', 'Volunteer Management Overseer', 'Oversees Volunteer Management department under the direction of HC-3. Works with TECH to determine which departments require technical training. Ensures good communication between Volunteer Management and all convention and hospitality departments. Coordinates with the What''s New Secretary for general updates using What''s New section for volunteers. Coordinates volunteer scheduling for convention departments and setup and teardown day(s). Oversees volunteer assignments and scheduling for hospitality departments. Oversees the development and delivery of curriculum common to all departments for general volunteer training.', 'An organized and steady overseer.  Must be able to delegate and show trust in the many coordinators.  Adaptable and patient.  Enthusiasm and full support for the IC will be important.', 1, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('e1ca0602-cac3-49ef-8458-911af9156f31', '11111111-0000-0000-0000-000000000005', 'Delegate Management Overseer', 'Oversees Delegate Management department under the direction of HC-3, looking for guidance in policy related matters. Works with TECH to determine which departments require technical training. Carefully considers staffing and specific skills required for each role involved with Delegate Management. Ensures good communication between DM scheduling coordinator and other HC departments such as Hotels, Airport, Activities, Transportation and Evening Gathering to get input for master schedule. Proposes FAQ updates and What''s New content to What''s New Secretary. Organizes emergency procedures (works with the Safety department). Gathers travel/hotel/tour information from delegates. Creates and distributes itineraries for all delegates.', '', 2, 4, '2026-05-02T01:16:57.027347+00:00'),
  ('33b45a30-73cc-4a9e-9cec-6a8446590e0f', '11111111-0000-0000-0000-000000000001', 'Transportation Overseer', 'Responsible for delegate related travel provided by the organization from arrival until departure, under the direction of HC-1. Oversight includes transportation to and from hotels, Branch Sponsored Tours, convention, other delegate activities, and transportation hubs such as airports, train stations, bus stations, and ports. Interfaces with bus companies and public transit officials. May assist in negotiating transportation rates. Oversees all aspects of training for the Transportation Department. Interacts with the delegate rooming overseer in determining safest locations for bus pick up and drop off at hotels. Interacts with HC-2 on transportation to and from activities. May propose content for Frequently Asked Questions related to transportation to HC-1. Collaborates with HC-1 to determine how to distribute mass transit tickets to delegates. May be involved in planning for the distribution of water according to the agreed upon Hydration Plan. Under the direction of the HC, may make special transportation arrangements for Branch representatives, as needed.', 'Availablity is key.  An exceptional delegator.  Transportation works with almost every other department within HC so this brother needs to be easy to get along with.  He should ne known for his reasonableness.', 3, 9, '2026-05-02T01:16:57.027347+00:00'),
  ('2b0406a3-d615-4e73-a337-f3d37188c8f9', '11111111-0000-0000-0000-000000000003', 'Encouragement Gathering Overseer', 'Oversees all aspects of the Evening Gathering program(s). Directs work of the evening gathering overseer assistants (Hospitality and Production). Approves the Evening Gathering Operating Plan for submittal to Hospitality Committee. Coordinates regular meetings with oversight team to provide training and to ensure good communication. Compiles and approves the Evening Gathering budget for submittal to the Hospitality Committee.', 'Spiritual man who can follow often changing direction.  He will diceminate informtaion/direction more often than he will be making decisions.  Brothers with SKE or Bethel training often excel in this role. Cannot be a brother with a tendancy to get stuck on his own ideas.', 4, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('aa09f844-5a20-4f8d-a764-00ec5db32db3', '11111111-0000-0000-0000-000000000001', 'Delegate Rooming Overseer', 'Responsible for all delegate related rooming matters at contracted hotels and homes for special rooming. Works with rooming coordinator to familiarize himself and his team with the contracted properties. Collaborates with the rooming coordinator to determine the size and location of Welcome Desks in each hotel. Maintains a clear understanding of contracted amenities and approved activities. Works with the Transportation overseer and hotel management to determine approved transportation pick-up and drop-off plan. Has oversight of all Delegate Rooming volunteers and training to ensure consistency across department.', 'Flexible and energetic.  CCCs are often used in his role becuaew of the many layers of planning and number of departments incolved.  Should have the abiity to oversee writting and implementing of complex opperating plans.  Should be known for working well with others.  Cannot be a brother with a tendancy to get stuck on his own ideas.', 5, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('764a0df2-6b9b-4516-880c-de2fffdf498f', '11111111-0000-0000-0000-000000000003', 'Activities Overseer', 'Oversees all aspects of the Activities Department under the direction of HC-2. Works closely with activities assistant overseer. Ensures good communication and collaboration between Activities Department and other Hospitality departments. Collaborates with the branch-sponsored tours coordinator, field service coordinator, and self-guided tours coordinator regarding website FAQ items, and submits recommendations to Hospitality Committee. Collaborates with the branch-sponsored tours coordinator and field service coordinator for all volunteer training. Coordinates the development of operating plans for each branch-sponsored tour. Coordinates regular meetings with Activities oversight team to train, shepherd, and ensure good communication. Coordinates with Delegate Management regarding delegate activity assignments. Communicates with Volunteer Management regarding volunteer needs and assignments.', '', 6, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('a47f2b63-b44e-420a-8fcf-e6e5a2c332f6', '11111111-0000-0000-0000-000000000001', 'Airport Overseer', 'Oversees all preparations needed at the airport(s) under the direction of HC-1. Under direction of HC-1, meets with airport personnel, oversees operating plans and emergency procedure development. Responsible for organizing the arrangements for delegate greetings and assistance upon arrival at transportation hubs. Collaborates with the Convention Committee to coordinate convention delegate greeting. Recommends the size and scope of greeters with HC-1 approval. Arranges and oversees all training, including scheduling training sessions and the preparation of training material.', 'Assignment will involve long hours moving from terminal to terminal. Must be proactive to anticipate delegate arrivals and reactive for sudden changes.', 7, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('e882a1c3-03cc-4fdc-a527-2fbb72140abe', '11111111-0000-0000-0000-000000000001', 'Transportation Overseer Assistant', 'Supports transportation overseer. May oversee one or more transportation methods, under the direction of the transportation overseer.', '', 8, 9, '2026-05-02T01:16:57.027347+00:00'),
  ('9178e0d9-7fd0-4e30-ad3a-a268a1ced052', '11111111-0000-0000-0000-000000000003', 'Encouragement Gathering Overseer Assistant (Production)', 'Oversees the work of layout/design coordinator, performance coordinator, and audio/video coordinator. Takes the lead in production development for all Evening Gathering content. Oversees all mandatory rehearsals. Submits a production budget to the evening gathering overseer for approval.', '', 9, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('7be3c016-3746-42bf-83a0-a9d9c700a057', '11111111-0000-0000-0000-000000000005', 'Volunteer Management Overseer Assistant', 'Supports volunteer management overseer. Provides basic technical assistance to congregation contact/service committee and departments as needed. Works directly with training coordinator and curriculum keyman.', '', 10, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('3b486fd8-051a-490d-a221-e107caeb93ee', '11111111-0000-0000-0000-000000000003', 'Activities Overseer Assistant (Field Service)', 'Assists with all aspects of activities overseer assignment. Works closely with tours keyman and VMSK to ensure volunteer needs are cared for.', 'Works closely with all congregations assigned to host delegates for field service. Good communication is essential, and should be highly organized with great attention to detail. Should work well under pressure and should be able to oversee several keymen & captains.', 11, 9, '2026-05-02T01:16:57.027347+00:00'),
  ('e460bbb9-378b-4afb-badb-f8d9eed4d58f', '11111111-0000-0000-0000-000000000001', 'Delegate Rooming Overseer Assistant', 'Supports delegate rooming overseer.', '', 12, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('a1ffc35c-fa39-4bd0-b618-f78a0cd1a693', '11111111-0000-0000-0000-000000000006', 'Attendant Overseer', 'Oversees all Attendants. Department size will be approximitely 1600 people.', 'Attentive and organized.  Calming influence.  Needs to excel at delegating', 13, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('8c472185-2205-4fee-896a-720ca4f8eb5c', '11111111-0000-0000-0000-000000000006', 'Parking & Transportation Overseer', 'Oversees Parking and Transportation of locals to and from convention. Department size will be approximately 600 people.', 'Attentive and organized. Calming influence. Needs to excel at delegating', 14, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('35e6ef5f-2fc7-4e03-a1ae-f290058d0a20', '11111111-0000-0000-0000-000000000002', 'Installation Overseer', '', '', 15, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('dc518035-6eab-42c0-95f4-73f3543a3f80', '11111111-0000-0000-0000-000000000005', 'Safety Overseer', 'Determines potential safety and emergency matters that could affect delegates and volunteers. Organizes emergency response procedures under direction of Hospitality Committee. Works with safety training coordinator to provide safety training for all hospitality departments. Coordinates with Convention First Aid Department to determine Delegate Safety''s role on convention days.', 'Highly organized.  LDC background can be helpful.  Must be able to interact with many HC departments and be yielding when he can.  ', 16, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('fe22cea2-76b3-45b6-9186-c21438644a13', '11111111-0000-0000-0000-000000000006', 'Parking Assistant (Mass Transit)', 'Oversees remote crews and Park-n-rides, brothers and sisters serving as ''guides'' on the trains, and the flow pf passengers to and from the venue.', 'This brother will oversee crews across a wide geographic area. He will need to be an excellent trainer, communicator, and delegator. He should have the availability to become thoroughly knowledgable with all remote lots and light rail lines and RTD functions. Local knowledge is especially valuable for this role.', 17, 9, '2026-05-02T01:16:57.027347+00:00'),
  ('c0a40e60-28c6-461a-b0d4-5f6408e6c749', '11111111-0000-0000-0000-000000000005', 'Safety Overseer Assistant (Hydration / Personnel)', 'Assists safety overseer and directly works with safety training, hydration plan, personnel, and emergency team coordinators.', 'Assists Safety Overseer and works directly with Safety Coordinators assigned to hospitality and convention departments. Needs to be able to organize, communicate and delegate well.', 18, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('3acb4c30-e99c-4fe3-9b02-6c2eedd058a3', '11111111-0000-0000-0000-000000000005', 'Delegate Management Overseer Assistant', 'Supports delegate management overseer. It may be beneficial for the overseer to handle some departments and the assistant to handle other departments. Final decisions should be approved by the delegate management overseer.', '', 19, 4, '2026-05-02T01:16:57.027347+00:00'),
  ('a738dd00-16eb-411f-bd29-ddbee21fb2ca', '11111111-0000-0000-0000-000000000001', 'Airport Overseer Assistant - Arrivals', 'Responsible for the implementation of the Airport Operating Plan with a focus on recieving dlegates as they arrive. Assists in developing operating plans, and ensures that final plans are followed.', 'Similar skills and qualities as the Airport Coordinator.  Hospitable.', 20, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b3760950-1364-4aa9-8f87-a69161866751', '11111111-0000-0000-0000-000000000002', 'Cleaning Overseer', '', '', 21, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('9a23b5eb-490d-450f-8a05-78f01e1704f3', '11111111-0000-0000-0000-000000000002', 'Trucking & Equipment Overseer', '', '', 22, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('c93b4c8e-b2b3-424f-9578-201a3fec5734', '11111111-0000-0000-0000-000000000004', 'AV Overseer', 'Oversees all AV installation and operations.  He will have an English and Spanish assistant for each of the typical department roles (Video, Audio, Stage).  ', 'Project management skills and Tech skills are more important than AV skills.  Most of the equipment will be new to the brothers, limiting the value of previous experience in AV at the Assembly Hall.  WHQ Broadcasting will be onsite to provide assistance and training. ', 23, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('b3ea563a-4b41-4512-88af-74eb68fd79e4', '11111111-0000-0000-0000-000000000005', 'Email/Call Center Coordinator', 'Responsible for Email and Call Center teams, providing continuous training and updates to secretaries and reviewers. Communicates with other departments to obtain answers to questions from delegates. Communicates requests from other departments to delegates. Monitors delegate communications regularly and along with the language coordinator utilizes the Official Inbox Team to assign all emails to secretaries. Ensures all communications with delegates are kind and loving. Notifies delegates via email to check the What''s New section when new articles are published.', 'Coordinates email and call center translation teams. Oversees all communication to delegates. Must possess discretion. Good organizer and communicator.  Must work well with the sisters and make them feel comfortable.  80-90% of those he works with regularly will be sisters.  ', 24, 1, '2026-05-02T01:16:57.027347+00:00'),
  ('0928f866-fa41-4fac-9ce0-b498e2044975', '11111111-0000-0000-0000-000000000003', 'Activities Overseer Assistant (Branch Sponsored Tours)', 'Assists with all aspects of activities overseer assignment. Works closely with tours keyman and VMSK to ensure volunteer needs are cared for.', '', 25, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('cabcc589-3548-4426-9adb-328fdd9a5564', '11111111-0000-0000-0000-000000000001', 'Airport Overseer Assistant -Transportation', 'Responsible for the implementation of the Airport Operating Plan with a focus on getting delegates from the Arrivals department to thier Transportation to their Hotel. Assists in developing operating plans, and ensures that final plans are followed.', 'Oversees a specific airport. Like the airport overseer, he will interact with airport administration to facilitate welcome of delegates. Should be known as a kind brother with good communication skills. Assignment will involve long hours moving from terminal to terminal. Must be proactive to anticipate delegate arrivals and reactive for sudden changes.', 26, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('7c690e3f-4be5-4fec-85dd-5c09239359ab', '11111111-0000-0000-0000-000000000003', 'Food Overseer', 'Oversees all aspects of Food Department, including food arrangements at branch sponsored tours, Evening Gathering(s) and the convention venue, under the direction of HC-2. Consults and communicates with the Hospitality Committee regarding food safety and policy-related matters. Collaborates with Convention Committee regarding venue and distribution locations of box lunches for convention days. Communicates with Volunteer Management regarding volunteer needs and assignments.', '', 27, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('4094cf57-19bc-463b-8686-f5af215bb61f', '11111111-0000-0000-0000-000000000006', 'Attendant Assistant (Interior)', 'Oversees lobbies, corridors, and all common areas.', '', 28, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('998cef7f-5c4d-4479-bfbb-2e166d9e2ba4', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Video - English)', '', 'Able to train and lead highly trained teams.  Will require travel to/from Denver area in late April/May for training and setup training.  ', 29, 5, '2026-05-02T01:16:57.027347+00:00'),
  ('bee78516-595d-4e8a-b8b8-dbd1d5e8680c', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Video - Spanish)', '', 'Able to train and lead highly trained teams.  Will require travel to/from Denver area in late April/May for training and setup training.  ', 30, 5, '2026-05-02T01:16:57.027347+00:00'),
  ('c4ce4cdd-e915-471e-adcb-880f776dee41', '11111111-0000-0000-0000-000000000003', 'Tour Keyman #1 Jeffco (or largest activity)', 'Oversees a specific tour under the direction of the branch-sponsored tours coordinator. Assists with the development of the operating plan for his assigned tour. Collaborates with food overseer regarding meal arrangements for delegates at his assigned tour. Oversees and coordinates on-site training of tour guides. Maintains good communication with venue management regarding all delegate, tour guide, and greeter activity. Works closely with HC-3 safety coordinator to identify safety concerns and implement safety protocols for his assigned tour. Collaborates with HC-1 Transportation regarding delegate pick-up and drop-off.', 'Must be an organized brother who understands how to construct and implement multi-faceted operating plans.  With larger activities, he will oversee 3-5 Keyman, 5-10 captains, and up to 400 volunteers.', 31, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b497c6bf-acbc-44f0-9742-964f483836f3', '11111111-0000-0000-0000-000000000002', 'Installation Assistant (Setup/Seating)', '', '', 32, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('90def78d-eaf3-4fb6-b882-cfbc8b56b588', '11111111-0000-0000-0000-000000000003', 'Encouragement Gathering Overseer Assistant (Hospitality)', 'Oversees the work of venue liaison, guest coordinator, installation coordinator and volunteer coordinator.  Maintains consistency at all venues if multiple venues for Evening Gatherings are rented. Submits a hospitality budget to the evening gathering overseer for approval.', 'Organized and a good communicator.  Strong project management skills.  Must be easy to work.  Patient and kind shepherd.', 33, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('2bbee1cf-be30-4be0-86ea-1274bdca3feb', '11111111-0000-0000-0000-000000000001', 'Pedestrian Travel Coordinator', 'Responsible for creating the logistics portion of the travel plan for all delegate activities associated with the convention. Coordination includes routing, mapping, signage, and determining access points to all pick-up and drop-off areas in collaboration with HC-2 for activities, and the Convention Committee parking overseer for convention days. Assures walking routes are direct and safe, considers exposure to the elements during the course of the day, and possible change in traffic patterns. Is responsible to investigate and study all possible routing, including the development of contingency plans. Investigates if, and where, road or rail closures are planned during the convention period. Considers if any other events in the convention city will impact planned routes. Oversees quick response vehicles including the vetting of drivers, insurance, and vehicles, whether rented or privately owned.', 'Responsible for creating entire logistics plan for delegates including routing, staging, drop off and pick up locations, and contingency plans. Requires a highly organized brother with excellent communication skills. Ability to create Gantt charts, Excel spreadsheets or other planning tools will be helpful. Helpful to have an understanding of the convention city transportation options, highways, and destination details. Should be able to accurately project travel times and potential challenges.', 34, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('5d7e5ecd-131c-4f16-8e64-87eeb5b49477', '11111111-0000-0000-0000-000000000005', 'Safety Overseer Assistant (Site / Transportation)', 'Assists safety overseer and works directly with safety coordinators assigned to Hospitality and Convention departments.', 'Assists Safety Overseer and works directly with Safety Coordinators assigned to hospitality and convention departments. Needs to be able to organize, communicate and delegate well.', 35, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('b2f8036b-0834-4095-be0c-653a57878044', '11111111-0000-0000-0000-000000000006', 'Attendant Assistant (Exterior)', 'Oversees sidewalks and plaza around the covention center.', '', 36, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('ce6f036f-8b1e-495f-9e2e-da4cbd17a617', '11111111-0000-0000-0000-000000000005', 'VM Scheduling Coordinator', 'Works with TECH to understand how scheduling tools function. Provides assistance to congregation contact/service committee and volunteers to help them understand the scheduling process. Makes sure as many as possible are given the opportunity to volunteer. Oversees and regularly monitors VM scheduling keymen.', '', 37, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('9a905980-18b4-461b-ad5d-fe71b86b1173', '11111111-0000-0000-0000-000000000001', 'Mass Transit Coordinator', 'Responsible for all delegate related public transportation arrangements for the convention period. May assist in negotiating, securing, and distributing public transportation tickets for delegates. Communicate, as needed, with mass transit officials regarding routing, load capacity, security, and the presence of attendants at stations. May work with mass transit administrators to provide additional trains or cars, if needed. Considers best travel itineraries in collaboration with the logistics coordinator. Collaborates with the Convention Committee and Convention Parking transportation group regarding delegate and local publisher convention travel on mass transit.', 'Works closely with the Transportation Overseer. Needs to be organized. Able to work long hours and respond quickly to changing circumstances. May at times communicate with city officials to coordinate and schedule routes and best times to travel.', 38, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('566bcb51-7800-4c81-bad8-b8698f089864', '11111111-0000-0000-0000-000000000003', 'Tour Key-Man #2 (Four Mile House or 2nd largest)', 'Oversees a specific tour under the direction of the branch-sponsored tours coordinator. Assists with the development of the operating plan for his assigned tour. Collaborates with food overseer regarding meal arrangements for delegates at his assigned tour. Oversees and coordinates on-site training of tour guides. Maintains good communication with venue management regarding all delegate, tour guide, and greeter activity. Works closely with HC-3 safety coordinator to identify safety concerns and implement safety protocols for his assigned tour. Collaborates with HC-1 Transportation regarding delegate pick-up and drop-off.', 'Must be an organized brother who understands how to construct and implement multi-faceted operating plans.  With larger activities, he will oversee 3-5 Keyman, 5-10 captains, and up to 400 volunteers.', 39, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('cc9af2af-49fa-4781-9af7-dc99570d55ad', '11111111-0000-0000-0000-000000000002', 'Information & Volunteer Service Overseer', '', '', 40, 4, '2026-05-02T01:16:57.027347+00:00'),
  ('a7654cc3-22f4-4adf-a3d4-b81bc235dda0', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Marriott DTC (400 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 41, 5, '2026-05-02T01:16:57.027347+00:00'),
  ('d0a0bf27-f082-442e-b53b-98330770af7e', '11111111-0000-0000-0000-000000000006', 'Parking Assistant (Drop-off/Pickup)', '', '', 42, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('ff4dc60f-9767-430c-aa2d-1631a5f1e844', '11111111-0000-0000-0000-000000000001', 'Wayfinder Coordinator', 'Oversees the training and presence of wayfinders and delegate escorts as needed along delegate walking routes. Assists the logistic coordinator with investigation and selection of safest walking routes. May use congregations not attending convention for this group of volunteers, if approved. Coordinates with HC-3 Safety to ensure hydration is readily available for the delegates while walking to and from delegate activities.', 'Works with multiple departments to provide hydration and direction to delegates. May require changing distribution points as need arises and may need to work with congregations not assigned to convention. Needs to be kind, loving, flexible, and patient.', 43, 10, '2026-05-02T01:16:57.027347+00:00'),
  ('39de56a4-7ac2-4c97-afcf-d5d1c33f443c', '11111111-0000-0000-0000-000000000006', 'First Aid Overseer', '', '', 44, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('ec3a7ef7-f8ca-46f6-bbfb-4f233dda846b', '11111111-0000-0000-0000-000000000005', 'VM Interview Coordinator', 'Works with departments to manage personnel requests and organize and track interview progress. Provides training to interview teams on best practices when conducting interviews. Coordinates with remote volunteer couples to assist with interviews (if approved by the SCC). Works with training coordinator to identify locations for interviews if requested. Works with Application Review Team to identify applications that are incomplete; arranges phone/zoom interviews to complete the applications.', '', 45, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('2ccf676d-e79a-404b-8758-ccd9ccf6ee4c', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Audio - English)', '', '', 46, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('60f33cd0-e37d-4f5e-a946-fc70226eada0', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Audio - Spanish)', '', '', 47, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('9d126f26-6b31-456a-a236-f81ed191eaf8', '11111111-0000-0000-0000-000000000001', 'Special Rooming Coordinator', 'Responsible for all Special Rooming arrangements. Is keenly interested in the care and comfort of all delegates under his assignment. Oversees the inspection of private home accommodations, ensuring such are properly rated. Using discretion, makes room assignments that acknowledge years of special full-time service and other relevant criteria. Communicates with host families and the Transportation overseer ensuring that delegates assigned special rooming have transportation to and from their assigned hotel. Maintains a sufficient number of rooms for unanticipated needs or emergencies.', 'Must excel at organization.  Hospitable.  Discernment.  This is a role where the wife can work side-by-side with her husband for much of the work.   If possible, select a couple who can both contribute to this important assignment.  ', 48, 9, '2026-05-02T01:16:57.027347+00:00'),
  ('6eeedfaf-8518-47ea-a292-f24ed1c6cc5e', '11111111-0000-0000-0000-000000000006', 'Parking Assistant (Vehicle Parking)', 'Oversses parking at lots and garages.', 'Organized, enthusiatic, possitive brothers excel at this role.', 49, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('3a5c0f17-5534-4089-ab9e-18876907c7e1', '11111111-0000-0000-0000-000000000003', 'Tour Key-Man #3 (Pike Place or 3rd largest)', 'Oversees a specific tour under the direction of the branch-sponsored tours coordinator. Assists with the development of the operating plan for his assigned tour. Collaborates with food overseer regarding meal arrangements for delegates at his assigned tour. Oversees and coordinates on-site training of tour guides. Maintains good communication with venue management regarding all delegate, tour guide, and greeter activity. Works closely with HC-3 safety coordinator to identify safety concerns and implement safety protocols for his assigned tour. Collaborates with HC-1 Transportation regarding delegate pick-up and drop-off.', '', 50, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('fbc493ce-c44b-4cd3-bd17-a1c4888589f7', '11111111-0000-0000-0000-000000000003', 'Tour Key-Man #4 (Food Tour or 4th largest)', 'Oversees a specific tour under the direction of the branch-sponsored tours coordinator. Assists with the development of the operating plan for his assigned tour. Collaborates with food overseer regarding meal arrangements for delegates at his assigned tour. Oversees and coordinates on-site training of tour guides. Maintains good communication with venue management regarding all delegate, tour guide, and greeter activity. Works closely with HC-3 safety coordinator to identify safety concerns and implement safety protocols for his assigned tour. Collaborates with HC-1 Transportation regarding delegate pick-up and drop-off.', '', 51, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('296b6a3b-262c-4282-bbe9-c79c425f9097', '11111111-0000-0000-0000-000000000003', 'Food Overseer Assistant', 'Assists with all aspects of the food overseer assignment. Obtains all delegate special dietary information from HC-3 and provides this information to the food overseer.', '', 52, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('ce9bae97-f28f-4553-8865-4efba8ec89f9', '11111111-0000-0000-0000-000000000006', 'Accounts Overseer', '', '', 53, 1, '2026-05-02T01:16:57.027347+00:00'),
  ('18447d31-5639-4d74-ba58-adacbfd1e65e', '11111111-0000-0000-0000-000000000001', 'Bus Coordinator', 'Responsible for all delegate related busing activity for the convention. Maintains direct interaction, and good communication, with one or more bus companies leading up to and over the course of the convention. Communicates bus routing and any final changes to the bus company dispatcher. Responsible for tracking bus usage, including participating in the audit of final invoicing. Maintains a detailed report of problems during the contract period.', 'Needs to be a good communicator, organized, and able to deal with both witnesses and non-witnesses kindly. Helpful, but not necessary, if he has an understanding of bus industry challenges and regulations, and is able to carefully address bus service issues.  Interacts directly with management at bus company regarding itineraries, routes, passenger manifests, and signage.  Will also assist in final audit of bus service. Will share in training of Bus Captains. May be involved with contract negotiations and final service adjustments.', 54, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('12c5c618-5dd5-45f2-9f86-c879d325bd19', '11111111-0000-0000-0000-000000000002', 'Cleaning Assistant (Seating -Spanish)', '', '', 55, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('48cacc9a-bf98-4824-b37b-7125c6e04221', '11111111-0000-0000-0000-000000000002', 'Cleaning Assistant (Seating -English)', '', '', 56, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('7246bc7a-fe86-4ec1-ac17-a16c336cb659', '11111111-0000-0000-0000-000000000004', 'Baptism Overseer', 'Oversees Baptism Pool installation and all Baptism arrangements.  He will have an English and Spanish assistant.  Due to the number of potential baptism candidates, this role requires the use of several Keymen to assist with traffic flow, changing room coordination, handling of candidates personal items, etc.  ', 'Organized.  Ability to see big picture.  No Baptism experience is needed for the Overseer role. 
', 57, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('e91d9f24-a12b-4d36-bba6-8f8a7f3c2093', '11111111-0000-0000-0000-000000000006', 'Attendant Assistant (Seating)', 'Oversees auditorium and seating sections.', '', 58, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('0220b269-3d63-4555-b5ea-7ea5ee404255', '11111111-0000-0000-0000-000000000006', 'Attendant Assistant (Seating - Spanish)', 'Oversees auditorium and seating sections.', '', 59, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('91482add-cf54-46bd-bfd6-8617208c7c63', '11111111-0000-0000-0000-000000000003', 'Performance Coordinator - DIRECTOR', 'Oversees the direction of the Evening Gathering program. Works closely with the Evening Gathering Branch Contact to develop each portion of the program. Responsible for pre- and post-production tasks, such as costumes, stage props and setup, program playlists, etc. Oversees the work of the costume and makeup team. Creates performance script and recruits/trains a script manager to ensure proper flow of the entire program.', 'Creative/music background would be beneficial. Needs to have good attention to detail. If possible, has production/stage/props background. Must be able to evaluate talent and provide direct feedback in a kind way. Humility and communication skills needed as he will be working closely with the evening gathering branch contact to develop and adjust the evening gathering program.', 60, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('bb8f251b-10f8-46ac-93c7-3ea715744549', '11111111-0000-0000-0000-000000000005', 'Hydration Plan Coordinator', 'Ensures that each delegate will have access to water/electrolytes when and where they need it most. Works to make sure each Hospitality department has an appropriate hydration plan in place. Considers weather and other factors that could affect amount of water/electrolytes needed. Works with appropriate convention departments to be sure they have hydration plans.', 'Coordinates and dispenses Hydration Plan to all hospitality departments and helps ensure plan is followed by all departments. Good communicator and organizer.', 61, 4, '2026-05-02T01:16:57.027347+00:00'),
  ('a109dea4-d48d-4520-93f6-c16fa7d54f22', '11111111-0000-0000-0000-000000000006', 'Parking Assistant (Congregation Contact/Support)', 'Communicates with congregations'' ''Transportation Key Man'' for the routing of charter busses, parking directions, DEDO passes, etc. Assists department in all administrative roles.', 'Needs to be exceptionally organized and a good communicator.', 62, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('4351a3c6-a771-4ec7-8fdf-5906b33502fc', '11111111-0000-0000-0000-000000000003', 'Field Service Coordinator (SMPW)', 'Coordinates Field Service SMPW arrangements under the direction of the activities overseer/assistant. Collaborates with HC-1 Transportation regarding delegate transportation. Collaborates with SMPW city overseer regarding cart locations and delegates assigned to participate in SMPW. Coordinates the documentation of preaching experiences and submits them to the activities overseer.', 'Good knowledge of SMPW guidelines and scheduling. Needs to be a good liaison between Activities Oversight and the SMPW City Coordinator. Capable of overseeing around 20 SMPW locations during the convention week.', 63, NULL, '2026-05-12T04:08:02.372631+00:00'),
  ('df734ff8-a61f-4339-92d2-0238db45bc74', '11111111-0000-0000-0000-000000000003', 'Congregation Field Service Coordinator (English)', 'Coordinates Field Service congregation arrangements under the direction of the activities overseer/assistant. Researches congregations and Kingdom Halls to host field service based on distance from hotels. Reviews the congregations and Kingdom Halls to be used for field service activity with the activities overseer/assistant. Reviews the Field Service Operating Plan for each congregation and submits to activities overseer/assistant prior to implementation. Collaborates with HC-1 Transportation regarding delegate transportation. Coordinates the documentation of preaching experiences and submits them to the activities overseer/assistant.', '', 63, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('266fbb8d-0261-4bae-b9fe-55199cb1c8ce', '11111111-0000-0000-0000-000000000003', 'Congregation Field Service Coordinator (Spanish)', 'Coordinates Field Service congregation arrangements under the direction of the activities overseer/assistant. Researches congregations and Kingdom Halls to host field service based on distance from hotels. Reviews the congregations and Kingdom Halls to be used for field service activity with the activities overseer/assistant. Reviews the Field Service Operating Plan for each congregation and submits to activities overseer/assistant prior to implementation. Collaborates with HC-1 Transportation regarding delegate transportation. Coordinates the documentation of preaching experiences and submits them to the activities overseer/assistant.', '', 64, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('bf58a98a-038e-4536-9fd6-a9b7d4ff29ca', '11111111-0000-0000-0000-000000000002', 'Rooming Desk', '', '', 65, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('a1af7332-6915-4736-a229-d4d43390559f', '11111111-0000-0000-0000-000000000001', 'Convention Greeter Coordinator', 'Organizes the greeting of delegates at the convention. Approximately 300-400 greeters will be used each day.  ', 'Kind.  Hospitable.  ', 66, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('dd6868b2-150f-48d3-8bae-1c8885ca58fa', '11111111-0000-0000-0000-000000000002', 'Trucking & Equipment Assistant (Trucking)', '', '', 67, 4, '2026-05-02T01:16:57.027347+00:00'),
  ('09e94c70-c41e-42fe-90de-dd1f3c616823', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Stage - English)', '', '', 68, 1, '2026-05-02T01:16:57.027347+00:00'),
  ('63012ad1-ebf5-4414-b16d-8c4c1896c628', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Grand Hyatt (250 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 69, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('39ececaa-cfa0-4948-9048-aca5ddd8ceb7', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Stage - Spanish)', '', '', 70, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('aeb13aa7-85ab-438d-ba3c-bcd9593ac4e9', '11111111-0000-0000-0000-000000000002', 'Cleaning Assistant (Lobbies, Common Areas, Meeting Rooms)', '', '', 71, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('f0cf2693-2148-4399-a81d-3ec7daa83cc0', '11111111-0000-0000-0000-000000000002', 'Cleaning Assistant (Trash)', '', '', 72, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('019b857b-b9a3-41f7-ac4c-6eb859c2f4d7', '11111111-0000-0000-0000-000000000002', 'Lost & Found Overseer', '', '', 73, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('683cbb8d-8d12-403e-873c-3b241f824bc7', '11111111-0000-0000-0000-000000000004', 'Technical Director (Spanish)', '', 'Experience as a TD is vital.', 74, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('df94a33f-ea8d-490f-b6a5-e2b909deeff1', '11111111-0000-0000-0000-000000000004', 'Technical Director (English)', '', 'Experience as a TD is vital.', 75, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('c25ec771-3d82-4ac3-bc54-968851bdfeb0', '11111111-0000-0000-0000-000000000001', 'Special Rooming Coordinator Assistant', 'Assists the special rooming coordinator with all aspects of his assignment. The quantity of special rooming assistants will vary based on the quantity of delegates requiring special rooming and the total number of homes to be considered.', 'Works closely with HC to identify and confirm private rooms are suitable for delegates. Needs to be organized and able to coordinate with others. Will need to be able to solve issues quickly and tactfully.', 76, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('db80b549-0d63-4289-a554-5ffc57399555', '11111111-0000-0000-0000-000000000006', 'Accounts Assistant (Contribution Boxes)', '', '', 77, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('9384fc05-e4d0-4652-a8fb-14094daa8d5c', '11111111-0000-0000-0000-000000000004', 'Video Keyman (Video Walls - English)', '', '', 78, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('a20db1e0-2209-404a-934d-b3fac9c40f56', '11111111-0000-0000-0000-000000000004', 'Audio Keyman (Speaker Install - English)', '', '', 78, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b42bed74-5354-47af-810f-f868a80c235a', '11111111-0000-0000-0000-000000000004', 'AV Assistant (IT/Streamed Event English & Spanish)', '', '', 78, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('46ef7727-d8cf-4b4e-8a23-ec41fd6c72ca', '11111111-0000-0000-0000-000000000004', 'AV Assistant (Ballroom & Meetings Rooms)', 'Oversees installation and operation AV in the Ballroom and Meeting Rooms.  The ballroom will be receive a feed from the primary stage in the exhibit halls.  During the program he ensures the stability of the feed and audio levels.  ', 'AV experience and the ability to operate on his own.  This brother should be one of you more experienced AV brothers.  ', 78, 5, '2026-05-02T01:16:57.027347+00:00'),
  ('92e20081-f623-4743-aa01-1a30c2f8c2ee', '11111111-0000-0000-0000-000000000002', 'Information & Volunteer Service Assistant (Volunteer)', '', '', 80, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b0fa92f8-2077-4f48-8563-225444e3030f', '11111111-0000-0000-0000-000000000002', 'Cleaning Assistant (Exterior)', '', '', 81, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('90b4fc5f-e650-4c4a-b551-820a19a5278c', '11111111-0000-0000-0000-000000000002', 'Installation Assistant (Signage)', '', '', 82, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('9a01c9cc-15b3-46c1-b01b-128eb2fdb979', '11111111-0000-0000-0000-000000000003', 'Tour Key-Man #5 (If Needed)', 'Oversees a specific tour under the direction of the branch-sponsored tours coordinator. Assists with the development of the operating plan for his assigned tour. Collaborates with food overseer regarding meal arrangements for delegates at his assigned tour. Oversees and coordinates on-site training of tour guides. Maintains good communication with venue management regarding all delegate, tour guide, and greeter activity. Works closely with HC-3 safety coordinator to identify safety concerns and implement safety protocols for his assigned tour. Collaborates with HC-1 Transportation regarding delegate pick-up and drop-off.', '', 83, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('2a2ca21c-3957-4cbf-acb4-a93843a104e9', '11111111-0000-0000-0000-000000000005', 'VM Scheduling Assistant', 'Assists scheduling coordinator. May work with VM scheduling keymen.', 'Manages personnel requests and tracks interview progress. Obtains missing information on volunteer applications from volunteer. Bulk of work takes place early in the process. Must possess people-skills as he interfaces directly with applicants. Good organizer and communicator.', 84, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('7e37b510-d353-40f3-a0de-5333da57f132', '11111111-0000-0000-0000-000000000003', 'Distribution Coordinator', 'Oversees the distribution of delegate lunches at the convention venue. Coordinates efforts with Trucking and Equipment Department to ensure timely delivery. Under the direction of the food overseer, selects key brothers who can deliver food to locations for branch representatives. Ensures that surplus food is distributed to distribution points that experience shortages.', 'Good organizer, needs to become familiar with implementing food safety principles, and able to oversee several captains. Works under the Food Overseer.', 85, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('63e03589-6bf9-4bcb-8eb2-a60ab3411252', '11111111-0000-0000-0000-000000000005', 'Field Service Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 86, 7, '2026-05-02T01:16:57.027347+00:00'),
  ('f6e58dda-9198-4b3a-9c58-f15f012bd9f2', '11111111-0000-0000-0000-000000000006', 'Accounts Assistant (Counters)', '', '', 87, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('14bff173-e280-4bba-b4a4-59adc0d02ffa', '11111111-0000-0000-0000-000000000005', 'Email/Call Center Coordinator Assistant', 'Supports the email and call center coordinator. Provides assistance with managing email and call center operations, training of secretaries and reviewers, and responding to delegate inquiries.', '', 88, 1, '2026-05-02T01:16:57.027347+00:00'),
  ('d22d9b5a-2527-41ae-ac33-4d96bd19d43e', '11111111-0000-0000-0000-000000000002', 'Installation Assistant (Stage/Baptism)', '', '', 89, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('6aaa66fd-a860-4742-a45f-f2857bb36f86', '11111111-0000-0000-0000-000000000005', 'DM Scheduling Coordinator', 'Works with TECH to understand how scheduling tools function. Works with contacts in key hospitality departments such as Activities, Hotels, Airport, Transportation, Field Service, and Evening Gathering to optimize proposed master schedule. Monitors SFTS applications. Prepares delegate itineraries. Oversees review of itineraries to look for discrepancies. Communicates closely with delegate management overseer and Hospitality Committee before publishing itinerary (delegate itinerary must be approved by the Branch before publishing). Makes the necessary adaptations to delegate itineraries as changes occur.', 'Project management skills and computer programming skills will be needed. Must have keen attention to detail and be able to communicate well. Must be very patient and flexible to changing schedules. Must be readily available for the entire duration of the delegate''s visit.', 90, 4, '2026-05-02T01:16:57.027347+00:00'),
  ('62f09b95-2ed7-47ed-a539-b124f91e66aa', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Slate (210 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 91, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('afd05cd3-4f5b-46a8-ba12-49d7d86765de', '11111111-0000-0000-0000-000000000006', 'Parking Assistant (Signs & Mobile Support)', 'Assists department is all administrative roles. He serves as full Assistant, but his functions are in support of the department. Think: Congregation Secretary.', 'Needs to be exceptionally organized and a good communicator.', 92, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('5f30c9b7-68f0-41ec-97f9-251537d134f8', '11111111-0000-0000-0000-000000000003', 'Food Safety Coordinator', 'Coordinates training for volunteers working with food at the convention and other venues in accordance with Food Safety Guidelines (A-124). Ensures that all food safety procedures are closely monitored during any handling of food. Completes a quality analysis or sampling of food boxes at designated stations. Monitors and ensures food quality, noting issues and discusses resolution with food overseer.', 'A background in food industry or restaurant management would be beneficial. Highly organized, detail oriented.', 93, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('0457b686-a5f5-4b4e-933c-4fe234062b5b', '11111111-0000-0000-0000-000000000006', 'Exterior Keyman (Entrances & Exits)', '', '', 94, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c29a5595-494e-45f7-ba76-2a0209af01f6', '11111111-0000-0000-0000-000000000005', 'DM Scheduling Assistant', 'Supports scheduling coordinator.', 'Project management skills and computer programming skills will be needed. Must have keen attention to detail and be able to communicate well. Must be very patient and flexible to changing schedules. Must be readily available for the entire duration of the delegate''s visit.', 95, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('215fa892-a7d5-4ce0-b50c-0c4532ab8a6f', '11111111-0000-0000-0000-000000000003', 'Guest Coordinator - Ecouragement Gathering', 'Works with transportation, food, and attendant keymen. Serves as the point of contact for Will Call guests picking up their Evening Gathering tickets onsite. Works with attendant keyman to develop a detailed greeting plan. Reviews the food menu and budget with food keyman before sending to evening gathering and food overseers.', 'Essentially serves as the ''Assembly Overseer'' for EG.  Warm, approachable, and highly attentive to guest needs. Convention attendant experience would be beneficial. Will be coordinating evening gathering guests needs with various departments in advance.', 96, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('19744b76-be9b-4715-93bb-7393184167a2', '11111111-0000-0000-0000-000000000006', 'Exterior Keyman (Sidewalks and Plaza)', '', '', 97, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('25f71e04-293e-4b41-bcad-225a53d92940', '11111111-0000-0000-0000-000000000002', 'Trucking & Equipment Assistant (Support)', '', '', 98, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('d8e99779-746c-4949-b20d-bab11b44cf36', '11111111-0000-0000-0000-000000000003', 'Audio/Video Coordinator- Ecouragement Gathering', 'Works closely with venue liaison to develop audio/video plan for the presentation and recording of the program. Works closely with performance coordinator and layout/design coordinator. Coordinates the work of sound, lighting, and video keymen for the presentation and recording of the program. Vets potential third-party vendors if equipment needs to be rented. Works with installation coordinator to track all equipment used and ensure return of all borrowed/rented equipment.', 'Needs to be an excellent communicator. Experience in the audio/video industry would be very beneficial. Should be able to oversee/install and maintain audio and video equipment. Skilled in performing cable connections and wiring accurately to ensure safety.', 99, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c72557ad-d1ae-49c3-a2cd-628bfc6fdd59', '11111111-0000-0000-0000-000000000005', 'Convention Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 100, 3, '2026-05-02T01:16:57.027347+00:00'),
  ('a162ca19-1c4c-444e-86b0-9d7073ea6cfd', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Magnolia (210 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 101, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('18ef0fbb-52db-480d-81e7-fae8a69337da', '11111111-0000-0000-0000-000000000006', 'Interior Keyman (Corridors)', '', '', 102, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('3c773e0b-4f98-46d4-82df-26430092e5f2', '11111111-0000-0000-0000-000000000001', 'Bus Dispatch (Command Center)', 'Responsible for the daily operations of busing activity. Supervises and participates in arrangements to monitor all bus movement and activity, from the time the buses first leave the yard, through the entire rental period. Maintains real time communication with bus captains and the bus company dispatch team(s). Carefully monitors bus progress in relation to the itinerary and promptly communicates any discrepancies to the bus coordinator. Works closely with the logistics coordinator to manage unexpected circumstances that require the use of quick response vehicles.', '', 103, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('5169fadd-cfcf-415f-8457-0c5db8433527', '11111111-0000-0000-0000-000000000003', 'Transportation Keyman- Ecouragement Gathering', 'Works directly with transportation overseer and HC-1 to develop a transportation plan for delegates attending the Evening Gathering. Collaborates with HC-1 Transportation to ensure that designated drop-off/pick-up locations are utilized.', '', 104, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('d071d793-a28d-448f-b7fa-5240d949a14c', '11111111-0000-0000-0000-000000000001', 'Convention Greeter Keyman (Greeters)', 'Two Keymen work under the Convention Greeter Coord, with this keyman focussing on the greeters.  As a team, they work with the airport overseer to coordinate the delegate welcome each morning of the convention. This role is implemented under the oversight of the airport overseer.', 'Oversees 300-400 greeters.  ', 105, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('799236d1-f358-46d0-aeb7-66e5b942db62', '11111111-0000-0000-0000-000000000006', 'Accounts Assistant (Security)', '', '', 106, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('58abc474-1e58-42e3-956d-bff376ea708a', '11111111-0000-0000-0000-000000000006', 'First Aid Assistant (Office)', '', '', 107, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('e7b84f58-27e8-4c07-ade8-167339a4d1ff', '11111111-0000-0000-0000-000000000005', 'Airport Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 108, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('0c8edffe-34e2-451f-84ee-58f7514a2d6b', '11111111-0000-0000-0000-000000000005', 'VM Training Coordinator', 'Monitors volunteers who have received Volunteer Management general training. Assists departments to identify and schedule locations for department level training (maintains master training location schedule). Provides needed materials for training sessions, provides suggestions for training if requested. Helps prepare training curriculum common to all departments.', 'Identifies and coordinates training locations for all hospitality departments. Monitors training curriculum progress. Good organizer and communicator.', 109, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('cf4bd0e4-195e-47d0-bfe4-174ba425d143', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Residence Inn (170 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 110, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('4fb999ee-ef93-4e7b-9dde-0abaede5e92f', '11111111-0000-0000-0000-000000000005', 'Safety Training Coordinator', 'Oversees high level safety training for all Hospitality departments. Works with creative team coordinator and office support to create materials for safety and emergency training. Works with safety overseer to produce local safety video.', 'Coordinates and dispenses Safety information to all departments. Works with CTC to create materials/training video for safety and emergency training. Good communicator and organizer.', 111, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b1cecc1f-d9bc-456e-ac78-369bf130a22c', '11111111-0000-0000-0000-000000000005', 'Transportation Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 112, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('2863a367-16d0-4342-9d75-e19d8c15572d', '11111111-0000-0000-0000-000000000005', 'Transportation Safety Overseer', 'Works with assigned Hospitality or Convention department(s) to ensure Safety, Emergency, and Hydration Plans are in place. Ensures properly trained safety volunteers are available to each department. Ensures physical site inspections take place as needed. Oversees a team of volunteers on call for emergencies.', 'Liaison between Safety and Transportation. Good communicator and organizer.', 113, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('82327f41-f0af-4334-8d48-fa1aefa60f22', '11111111-0000-0000-0000-000000000005', 'Evening Gathering Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 114, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('98c8cea6-71ce-408c-b90b-24148a1acf93', '11111111-0000-0000-0000-000000000005', 'Activities Volunteer Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 115, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('217ce987-22e3-491d-8300-aedeb3005b11', '11111111-0000-0000-0000-000000000001', 'Airport - Command Center Coordinator', 'Supports Arrivals Assistant Overseer.  Oversees Airport dept at Command Center', 'Similar skills and qualities as the Terminal Overseer.', 116, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('82b1ddfa-d9b2-49f9-9175-1986929763f0', '11111111-0000-0000-0000-000000000003', 'AV Coordinator- Ecouragement Gathering', 'Works closely with venue liaison to develop audio/video plan for the presentation and recording of the program. Works closely with performance coordinator and layout/design coordinator. Coordinates the work of sound, lighting, and video keymen for the presentation and recording of the program. Vets potential third-party vendors if equipment needs to be rented. Works with installation coordinator to track all equipment used and ensure return of all borrowed/rented equipment.', 'Needs to be an excellent communicator. Experience in the audio/video industry would be very beneficial. Should be able to oversee/install and maintain audio and video equipment. Skilled in performing cable connections and wiring accurately to ensure safety.', 117, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('cf9b20c2-7fb4-4b89-abab-92c2a88dcbb1', '11111111-0000-0000-0000-000000000001', 'Convention Greeter Keyman (Singers)', 'Two Keymen work under the Convention Greeter Coord, with this Cayman focussing on the welcome chorus.  As a team, they work with the airport overseer to coordinate the delegate welcome each morning of the convention. This role is implemented under the oversight of the airport overseer.', 'Does not need to have music background, but it does help.  ', 118, 6, '2026-05-02T01:16:57.027347+00:00'),
  ('1bbf131b-d69e-4a6f-b2ac-0e0abc335536', '11111111-0000-0000-0000-000000000002', 'Cleaning Assistant (Support)', '', '', 119, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('ef9e5ca0-6e57-44b9-b066-b125358627c8', '11111111-0000-0000-0000-000000000005', 'Email/Call Center Coordinator Keymen', '', '', 120, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('276eace4-dfe9-48b3-9496-374a969c460f', '11111111-0000-0000-0000-000000000003', 'Volunteer Coordinator- Ecouragement Gathering', 'Works with HC-3 and Volunteer Management to ensure adequate volunteers are staffed for Hospitality and Production teams. Collaborates with evening gathering overseer and VM scheduling keyman to minimize scheduling conflicts. Coordinates check-in procedure for rehearsals and communicates attendance to evening gathering overseer assistant (Production).', 'Coordinates volunteer needs for the evening gathering. Warm and personable. Helpful in organizing and filling open assignments with the evening gathering.', 121, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('a4e9b77f-a7ce-4de1-96d6-04e3204ed301', '11111111-0000-0000-0000-000000000006', 'First Aid Assistant (Response Teams - Spanish)', '', '', 122, NULL, '2026-05-02T01:16:57.027347+00:00'),
