  ('53c236de-c93e-4dab-8ed6-19ea33b18bbe', '11111111-0000-0000-0000-000000000005', 'Emergency Team Coordinator', 'Oversees the creation of protocols for the Call Center function and for Quick Response Vehicles (QRVs) to operate during events and the convention weekend. Oversees scheduling and procedures for Call Center support. Closely collaborates with HC-1 logistics coordinator and QRV keyman to ensure that emergency transportation is readily available for delegates for safety and health emergencies, potentially reserving one or two QRVs and assigned drivers for delegate safety needs.', 'Organizes and manages qualified medical personnel. Good communicator and organizer. Good leader, can stay calm during emergency situations.', 128, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('40ca4d7b-3a39-481c-be26-7dfd1894f5d7', '11111111-0000-0000-0000-000000000006', 'Interior Keyman (Lobbies)', '', '', 129, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c1bc6d3e-2017-4a29-a9f1-3fdf597d3c51', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant #1 - Marriot DTC (400 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 130, NULL, '2026-05-02T01:16:57.027347+00:00'),
