  ('d7497a60-6700-4c40-a36e-550688e412c6', '11111111-0000-0000-0000-000000000006', 'Attendant Assistant (Support)', 'Admin support for the Attendant Dept.  Serves important function of coordinating the efforts of the assistants.', '', 135, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('caaed05d-20d5-48a0-aac3-70a364ea899d', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Hampton/Homewood (180 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 136, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b91d57c6-6161-4ff4-9791-73d8454f2b91', '11111111-0000-0000-0000-000000000006', 'Communications Assistant (Call Center)', '', '', 137, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('76ad77b4-191a-4d86-9873-a9ee137da853', '11111111-0000-0000-0000-000000000001', 'Quick Response Vehicles Coordinator', 'Responsible for the QRV pool including the vetting and dispatch of vehicles and drivers. Responsible for rental van pool. With the logistics coordinator, interfaces with the mass transit coordinator, bus coordinator, HC-3 Safety and Convention First Aid, to ensure that all delegate needs requiring immediate transportation are addressed. Maintains presence in the Command Center. Works closely with bus dispatcher to assist in returning bus captains to their vehicles. Provides general support for all transportation needs involving QRVs surrounding convention days.', '', 138, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('5333cd72-f633-48a9-b281-6683a3330159', '11111111-0000-0000-0000-000000000001', 'Quick Response Vehicles Coordinator Assistant', 'Provides shuttle services for delegates and guests as directed by means of rented shuttle vans, or if approved, personal vehicle. Must meet qualifications outlined in the Volunteer Driver Agreement form. Should be known for being responsible, cordial, and safety-conscious individuals that make others feel comfortable in their presence.', '', 139, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('9b46451e-eb9b-45c9-8720-7d5ff059f706', '11111111-0000-0000-0000-000000000001', 'Bus Dispatch Assistant', 'Supports bus dispatcher.', '', 140, NULL, '2026-05-02T01:16:57.027347+00:00'),
