  ('46ea447f-c503-4eda-96ce-7903d54e0de7', '11111111-0000-0000-0000-000000000001', 'Mass Transit Coordinator Assistant', 'Supports mass transit coordinator.', 'Similar skills and qualities as the Mass Transit Coordinator.', 153, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('82d2ab98-e932-4ce2-9fd4-aa9d55459e13', '11111111-0000-0000-0000-000000000005', 'Welcome Package Coordinator', 'Works under the direction of the delegate management overseer and Hospitality Committee early on to plan for a delegate welcome package in harmony with teaching instructions and convention desk input. Offers suggestions and anticipated costs of various items that may be included. Organizes approved work/welcome items that may be provided by local congregations. Handles badge printing or other approved information for welcome package.', 'Under the direction of the HC, will coordinate welcome package preparation and distribution. Manages badge printing for all delegates. Good organizer and communicator.', 154, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('9cf26ba6-9c14-4181-9339-76a15ff0d057', '11111111-0000-0000-0000-000000000001', 'Bus Coordinator Assistant', 'Supports bus coordinator.', 'Similar skills and qualities as the Bus Coordinator.', 155, NULL, '2026-05-02T01:16:57.027347+00:00'),
