  ('cc1f7561-bf44-455a-ab75-c2672b719f61', '11111111-0000-0000-0000-000000000003', 'Food Safety Coordinator Assistant', 'Works closely with the food safety coordinator. Coordinates locations where food safety meetings will be held.', 'Similar skills and qualities as the Food Safety Coordinator.', 165, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b4753e2b-2d04-40c9-aaf2-374bd649ab6e', '11111111-0000-0000-0000-000000000003', 'Installation Coordinator- Ecouragement Gathering', 'Works with venue liaison if venue allows volunteers to assist with any setup for the Evening Gathering. Coordinates all installation activity with Assembly Hall overseer (if Assembly Hall is used). Works with safety keyman to develop a safety plan during setup and breakdown of equipment. Works with audio/video coordinator to ensure the return of all borrowed/rented equipment (if needed).', 'Works well with brothers in oversight. Convention Installation, LDC, Assembly Hall experience is beneficial. Will be assisting with evening gathering setup which will include advance planning and coordination.', 166, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('7304db9a-4af1-4bf9-9d9f-6286db64673e', '11111111-0000-0000-0000-000000000002', 'Seating / Setup Keyman (Floor)', '', '', 167, NULL, '2026-05-02T01:16:57.027347+00:00'),
