  ('4797ac38-c458-4a88-821a-893417b6b524', '11111111-0000-0000-0000-000000000005', 'Evening Gathering Safety Coordinator', 'Works with assigned Hospitality or Convention department(s) to ensure Safety, Emergency, and Hydration Plans are in place. Ensures properly trained safety volunteers are available to each department. Ensures physical site inspections take place as needed. Oversees a team of volunteers on call for emergencies.', 'Liaison between Safety and Evening Gathering. Good communicator and organizer.', 170, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('f2a3464a-28c9-40b3-b47c-be82cfdd2ba6', '11111111-0000-0000-0000-000000000005', 'Activities Safety Coordinator', 'Works with assigned Hospitality or Convention department(s) to ensure Safety, Emergency, and Hydration Plans are in place. Ensures properly trained safety volunteers are available to each department. Ensures physical site inspections take place as needed. Oversees a team of volunteers on call for emergencies.', 'Liaison between Safety and Activities. Good communicator and organizer.', 171, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('12487000-237e-4659-9e25-d723cf198e74', '11111111-0000-0000-0000-000000000005', 'Hotel Safety Coordinator', 'Works with assigned Hospitality or Convention department(s) to ensure Safety, Emergency, and Hydration Plans are in place. Ensures properly trained safety volunteers are available to each department. Ensures physical site inspections take place as needed. Oversees a team of volunteers on call for emergencies.', 'Liaison between Safety and Hotels. Good communicator and organizer.', 172, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('bec0b13c-b4f9-4731-846e-2b7d747995c0', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - HGI Downtown (100 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 173, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('35c7aca6-6260-400d-a4f1-616f2182bfee', '11111111-0000-0000-0000-000000000001', 'Quick Response Vehicles Keyman', 'Responsible for the QRV pool including the vetting and dispatch of vehicles and drivers. Responsible for rental van pool. With the logistics coordinator, interfaces with the mass transit coordinator, bus coordinator, HC-3 Safety and Convention First Aid, to ensure that all delegate needs requiring immediate transportation are addressed. Maintains presence in the Command Center. Works closely with bus dispatcher to assist in returning bus captains to their vehicles.', '', 174, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b06da39a-5660-4c38-a8ed-60304ecab908', '11111111-0000-0000-0000-000000000002', 'Signage Keyman (Main Level, Ballroom Level)', '', '', 175, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('9077c85a-0ac6-44e3-86f6-e24ce1b04a18', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Hampton Ridegate (90 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 176, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('20335092-9ff8-4a2f-b949-e0cd995ad372', '11111111-0000-0000-0000-000000000005', 'Safety Scheduling Keyman', 'Works with assigned department to monitor volunteer needs. Works to build a good relationship with departments so they will trust Volunteer Management and the scheduling process. Assists congregation contact/service committees that are delaying in processing applications. Can assist with Email/Call center to provide assistance with application questions.', '', 177, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('67b9233d-0341-4008-9724-c3a34f72fbf0', '11111111-0000-0000-0000-000000000002', 'Trash Bins', '', '', 178, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('f4908e2a-63a3-4054-952b-09cd7b0dae06', '11111111-0000-0000-0000-000000000002', 'Information Keyman (Exhibit Level)', '', '', 179, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c66c7985-5f21-4c6d-91e7-5d84246547fe', '11111111-0000-0000-0000-000000000002', 'Recycling', '', '', 180, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('4ecefa38-de69-4892-a205-e3813078680c', '11111111-0000-0000-0000-000000000002', 'Information & Volunteer Service Assistant (Information)', '', '', 181, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('7aecc6f3-dcca-45c4-b2a3-ea5bdb5ffa14', '11111111-0000-0000-0000-000000000002', 'Bio Spills Keyman (Main Level, Ballroom Level)', '', '', 182, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('d0266376-842e-42ec-aacc-fca3b7f48a46', '11111111-0000-0000-0000-000000000003', 'Attendant Keyman- Ecouragement Gathering', 'Oversees all attendants at each Evening Gathering performance. Works with convention attendant overseer and HC-3 to ensure enough qualified attendants are staffed at each performance. Ensures all attendants are familiar with the emergency evacuation plan for all Evening Gathering locations and can implement it as necessary.', '', 183, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('54ffd224-7d89-4dc9-9740-f419ef1b1cec', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Centric (90 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 184, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('11d1eea0-ac88-4296-a280-16ac62c6c343', '11111111-0000-0000-0000-000000000002', 'Bio Spills Keyman (Exhibit Level)', '', '', 185, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('71455b98-1301-41d5-ac0f-8e126b6bd2da', '11111111-0000-0000-0000-000000000003', 'Cleaning Keyman (Ecouragement Gathering)', 'Coordinates all cleaning efforts at any venues rented, or Assembly Halls, used for the Evening Gathering program(s). Works with venue liaison coordinator and Assembly Hall overseer to develop detailed Cleaning Plan (if Assembly Hall is used). Determines the number of cleaning volunteers needed following each Evening Gathering performance.', '', 186, 5, '2026-05-02T01:16:57.027347+00:00'),
  ('a1756a31-3cb6-497d-9e73-5254472169a1', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Residence Inn (170 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 187, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('fb8e1cf6-867c-4ed0-883f-ea55af642c7a', '11111111-0000-0000-0000-000000000003', 'Parking Keyman- Ecouragement Gathering', 'Works under the direction of the venue liaison coordinator to ensure enough parking attendants are assigned for each performance. Oversees all parking facilities including offsite parking lots that are used in connection with the Evening Gathering. Works closely with the transportation keyman to ensure adequate space is reserved for buses. Works with venue liaison coordinator to develop parking plan with recommended routes to offsite parking locations.', '', 188, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('ab2934fd-ef65-46f6-83e6-29e728eba595', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Sonesta (150 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 189, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('aaccdc0a-5769-4eb0-8abd-35859a3f3d6e', '11111111-0000-0000-0000-000000000003', 'Safety Keyman- Ecouragement Gathering', 'Works with HC-3 Safety to identify and resolve all potential safety hazards at all rehearsal locations and venues being used. Attends all safety meetings in connection with the Evening Gathering. Works closely with the installation coordinator during setup and teardown.', '', 190, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('e272b928-e67a-4aaa-9e0f-ecea287a2db1', '11111111-0000-0000-0000-000000000004', 'Audio Keyman (Mixer - Spanish)', '', '', 191, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('e224e20e-a97c-40a5-9259-7742dfc7409c', '11111111-0000-0000-0000-000000000004', 'Audio Keyman (Mixer)', '', '', 192, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b951d6ca-82c1-428c-bbb0-796037313bce', '11111111-0000-0000-0000-000000000002', 'Lost & Found Assistant (Exhibit Level)', '', '', 193, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('31db64d8-d03d-4dec-bbd0-f5f9017610f9', '11111111-0000-0000-0000-000000000002', 'Lost & Found Assistant (Main Level, Ballroom Level)', '', '', 194, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('ef831d3d-1065-4bf3-9081-989deeda8cfb', '11111111-0000-0000-0000-000000000002', 'Stage Keyman', '', '', 195, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c93ad7f0-9bc8-41ea-a516-fe3202076439', '11111111-0000-0000-0000-000000000001', 'Bus Captains Keyman', 'Reports directly to the bus dispatcher. Serves as the Transportation Department contact on a bus for a specific route. Interfaces with the bus driver regarding routing, parking, disembarking, and scheduled pick-up. Ensures that delegate emergencies arising during transportation on buses are addressed providing basic care, prepared to call HC-3 Safety or 911 depending on severity of situation. Must be an elder or ministerial servant, and if married, preferably assisted by his wife. Receives delegates who have been organized by hotel welcome desks or activity guides into groups, and assists them onto their assigned bus. Accounts for all delegates before departure and alerts bus dispatch of any missing passengers. Announces general information, safety reminders, and may play pre-recorded programs approved by oversight to provide a lively atmosphere on longer bus trips.', '', 196, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b0549810-8f77-41cf-9869-2212d2dc6f8a', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assistants', 'Supports hotel coordinator.', 'Similar skills and qualities as the Hotel Coordinator. (One Hotel Coordinator Assistant per Hotel)', 197, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('3bdd3d26-aa1f-456c-ae2d-c1e154c7b8c7', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator - Staybridge Suites (65 Rooms)', 'Responsible for all delegate related matters within a single hotel or hotels. Hotel coordinators and assistants should be hospitable, energetic elders, preferably with previous Convention Rooming experience. This assignment may require being on call 24/7 while delegates are present in hotel. Works with hotel management to ensure that welcome desks, signage, delegate breakfast, auxiliary rooms, and other contracted amenities are available. Oversees the Welcome Desk and runners for the hotel. Arranges for the delegate orientation to be given. Collaborates with the bus coordinator to determine pick-up and drop-off locations and delegate loading procedures. Works closely with HC-2 if Evening Gathering is being held in a ballroom in his assigned hotel.', '', 198, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('6c7ecda9-1b26-4e2a-921d-4a37594b872d', '11111111-0000-0000-0000-000000000002', 'Seating / Setup Keyman (Exhibit Level)', '', '', 199, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b0aa88bb-7c02-43bb-a28c-e476444f74e3', '11111111-0000-0000-0000-000000000003', 'Self Guided Tour Coordinator', 'Oversees Self-Guided Tours under the direction of the activities overseer. Researches tours and attractions that delegates could visit on their own and provides recommendations for self-guided tours to activities overseer. Negotiates discounted rates with self-guided tour providers when possible.', 'Self-starter, good business sense, and can negotiate discounts at city attractions/restaurants. Good discretion and knowledge of interesting locations in the city and surrounding areas for potential locations to be visited.', 200, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('020dcd76-338b-4a00-be0f-aa78fa83ac80', '11111111-0000-0000-0000-000000000002', 'Seating / Setup Keyman (Main Level, Ballroom Level)', '', '', 201, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('844b7713-0138-4570-9e04-c9bcd2915419', '11111111-0000-0000-0000-000000000006', 'Signs & Mobile Support Keyman (Signs)', '', '', 202, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('fcc2e3d6-8a94-48ff-8b47-4f97fb7d7eb0', '11111111-0000-0000-0000-000000000006', 'Safety Assistant (Exterior)', '', '', 203, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('4bb8cdd8-6151-4f5c-b9aa-9650ef01b524', '11111111-0000-0000-0000-000000000006', 'Safety Assistant (Interior)', '', '', 204, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('7d2adb39-c9f8-419f-8022-fac9a4fc1cb3', '11111111-0000-0000-0000-000000000005', 'Convention First Aid Liaison', 'Communicates with Convention First Aid to ensure personnel and resources are shared between the two departments. Under the direction of the safety overseer, establishes and communicates response roles and boundaries with Convention First Aid to ensure proper care during convention days.', 'Liaison between Safety and Convention First Aid. Good communicator and organizer.', 205, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c7a162bc-d413-45a9-bfa9-dab6a0abb86f', '11111111-0000-0000-0000-000000000006', 'Exterior Keyman (Drop Off + Pickup)', '', '', 206, 8, '2026-05-02T01:16:57.027347+00:00'),
  ('5736586a-7eed-40c7-8ebc-da7731e46ec5', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Slate (210 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 207, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('4d6b3e97-8a7d-4a2c-8b3e-4a967267df85', '11111111-0000-0000-0000-000000000004', 'Audio Keyman (Inventory - Spanish)', '', '', 208, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('586455fb-6fa4-439e-bb29-37efde2e8d12', '11111111-0000-0000-0000-000000000004', 'Audio Keyman (Inventory)', '', '', 209, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('665ac24b-e15a-421b-8ec9-9b1968e9672c', '11111111-0000-0000-0000-000000000004', 'Video Keyman (Cameras - Spanish)', '', '', 210, 1, '2026-05-02T01:16:57.027347+00:00'),
  ('b3f0a91d-92bd-4c75-b68d-6b76a5854ce9', '11111111-0000-0000-0000-000000000004', 'Video Keyman (Cameras - English)', '', '', 211, 1, '2026-05-02T01:16:57.027347+00:00'),
  ('0e3863df-babc-4344-8247-3d5664c15d84', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Hilton Denver (200 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 212, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('2ce42f87-d1eb-4c81-8a11-8ca263ea456f', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Rennaissance City Center (100 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 213, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('0bb5c2ad-6dcb-49eb-97ce-4ecc4dfd0151', '11111111-0000-0000-0000-000000000002', 'Installation Assistant (Support)', '', '', 214, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('07d7f744-1d2b-4c21-8179-6b1bcaf9eafb', '11111111-0000-0000-0000-000000000003', 'Distribution Coordinator Assistant', 'Works closely with the distribution coordinator. Works closely with VM scheduling keyman to ensure volunteer needs are cared for.', 'Similar skills and qualities as the Distribution Coordinator.', 215, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('040a569a-482b-4e13-9936-61c5a308f1ac', '11111111-0000-0000-0000-000000000001', 'Airport Information Desk Keyman', 'Responsible for all information desk related volunteers, runners, and gate escorts (if used) during his assigned shift. Communicates with the airport terminal overseer regarding delegate arrival changes. Responsible for checking in delegates, answering delegate questions, and arranging for the care of any delegate special needs upon their arrival.', '', 216, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c83b8212-5878-4695-bdfd-57e963f9694d', '11111111-0000-0000-0000-000000000003', 'Musicians Keyman', 'Oversees auditions of musicians, singers, conductors, and musical directors. Directs recording sessions, rearranges compositions and different production techniques for a high-quality Evening Gathering program. Works with audio/video coordinator to ensure all rehearsal locations have appropriate setup for Evening Gathering program.', '', 217, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('5ef633f1-c02b-4416-a818-90f685e55f1e', '11111111-0000-0000-0000-000000000003', 'Decoration Keyman- Ecouragement Gathering ', 'Creates the decoration plan for food preparation and serving at the Evening Gathering. Works closely with the installation coordinator and food keyman to create the layout where food will be served at the Evening Gathering. Works closely with the venue liaison to ensure Assembly Hall overseer agrees with the decoration plan (if the Assembly Hall is used).', '', 218, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('67c41856-8f2b-4441-a532-f2a9840049a6', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Holiday Inn Express (150 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 219, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('c51f4315-88d0-40f8-989a-45d30d2e6d19', '11111111-0000-0000-0000-000000000003', 'Choreography Keyman', 'Works with Evening Gathering branch contact to compose the performance of dance related to the Evening Gathering. Organizes interviews and auditions of dancers and choreographers. Serves as a point of contact to support members of the choreography team when questions arise.', '', 220, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('1ca45d4b-d409-46b2-b00c-23176db92611', '11111111-0000-0000-0000-000000000003', 'Layout / Design Coordinator- Ecouragement Gathering', 'Works closely with performance coordinator and audio/video coordinator. Prepares the audience floor layout, locations and spacing for stage, band, booths, backstage, food services, etc. Works closely with venue liaison coordinator to ensure evacuation plan and backstage access routes are developed. Works with performance coordinator for movement of staff and performers to ensure proper placement queue and performance readiness.', 'Creative and detail oriented. Experience in the design industry is beneficial. Oversees costumes, props, and stage design keymen for the evening gathering.', 221, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('be813df0-a8ce-42c4-817d-ebd523cdf6fc', '11111111-0000-0000-0000-000000000003', 'Chorus/Singers Keyman', 'Works closely with the performance coordinator to arrange musical score for the evening gathering. Organizes interviews and auditions of musicians, singers, conductors, and musical directors. Serves as a point of contact to support members of the chorus when questions arise.', '', 222, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('a92b22fc-6ab5-4c06-bed8-171c8acb24ef', '11111111-0000-0000-0000-000000000003', 'Costumes/Makeup Keyman', 'Oversees a team of volunteers who will coordinate all makeup for the cast before and during the Evening Gathering. Works with venue liaison to ensure a designated space or private room is secured for the makeup team to work for all performances. Works with props keyman to procure props/costumes through volunteers who may have access to donated items that can be used for the Evening Gathering. Identifies and helps coordinate the assignments of makeup artists, costume purchases, and seamstresses. Works with performance coordinator to provide feedback to all cast members if costume changes are needed prior to Evening Gathering.', '', 223, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('681ab198-a4a6-4375-9ee1-cce8204d56c6', '11111111-0000-0000-0000-000000000003', 'Props Keyman- Ecouragement Gathering', 'Oversees procurement and purchase of all items used by cast and crew other than costumes. Searches volunteer database for skilled carpenters and painters needed for stage sets. Works closely with backstage and auditorium keyman for props and set changes as needed during the Evening Gathering. Works with evening gathering overseer to ensure rehearsal location(s) have moderate stage props and sets to mimic the Evening Gathering stage.', '', 224, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('85dc89a4-8435-4b5a-a2f5-c903d1ac3026', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - Aloft (120 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 225, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('93a08f85-3512-4136-9dc2-f61491efdd31', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - HGI Downtown (100 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 226, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('e9fff866-d6b1-4ca4-9ade-71a33c19806b', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant- Hampton Ridegate (90 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 227, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('736efdfb-1725-4373-a8e1-264f4b2cc74a', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator  Assitant- Hampton/Homewood (180 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 228, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('0f36eb60-c838-4eb7-a26f-f1c349a2daf7', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant - SpringHill Suites (100 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 229, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('41870ee8-1a07-4dcf-8df4-f57d5a539aa1', '11111111-0000-0000-0000-000000000003', 'Volunteer Support & Safety Keyman- Ecouragement Gathering', 'Works closely with the evening gathering overseer to maintain the master schedule of cast member volunteer assignments. Works closely with volunteer coordinator under evening gathering overseer assistant (Hospitality) to fill additional cast members as needed. Sends approved correspondence to all cast members for rehearsal times and locations and oversees check-in desk for rehearsal attendance. Works with safety keyman under the oversight of the evening gathering overseer assistant (Hospitality) to ensure at least one safety overseer or keyman is present at all rehearsal locations.', '', 230, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('d9016ca6-788a-4377-8bca-9891c2ba84d9', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator  Assitant- HGI Tech Center (100 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 231, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('d33aa62e-bd73-4d9d-af64-1cfb2cc20181', '11111111-0000-0000-0000-000000000003', 'Sound Keyman- Ecouragement Gathering', 'Works closely with the audio/video coordinator to ensure a quality sound experience at the Evening Gathering. Collects, edits and creates sound effects for the program as needed. Provides suggestions to Evening Gathering Branch Contact for the use of interactive media and sound effects to enhance the musical content. Works closely with chorus/singers keyman at all evening gathering rehearsals. Assists installation coordinator with setup and teardown of all music equipment before and after all Evening Gathering performances. Works closely with the audio/video coordinator to ensure a quality recording of the Evening Gathering program is obtained.', '', 232, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('8466b16a-4be6-41c9-a928-31ba8039ce62', '11111111-0000-0000-0000-000000000003', 'Backstage & Auditorium Keyman', 'Oversees all backstage access and ingress/egress set movement during all evening gatherings. Works with performance coordinator to communicate last minute changes to cast and crew for queues and entrances during performance. Works with vendor liaison to ensure backstage entrances have attendant presence before and during all performances. Works with evening gathering overseer to provide setup and backstage assistance at all Evening Gathering rehearsal locations.', '', 233, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('bb63a6d1-458c-4864-952a-39a65ae6d278', '11111111-0000-0000-0000-000000000003', 'Video: TD / Cameras', 'Oversees all video and IT related content for the Evening Gathering. Responsible for vetting volunteers with video and IT experience. Works closely with performance coordinator to ensure all media content for each act in the Evening Gathering is a high-quality presentation. Prior to each performance will hold meetings with crew to go over camera shots and coordinate a variety of checks to capture quality content. During the performance will determine when to roll video and audio elements and when to cue talent. Works closely with the audio/video coordinator to ensure a quality recording of the Evening Gathering program is obtained.', '', 234, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('ad924465-2df7-475a-8a75-fc8c06e2dd72', '11111111-0000-0000-0000-000000000003', 'Vendor Liaison Assistant', 'Works closely with the vendor liaison. Spot checks lunches at the convention to ensure food safety is being maintained and reports findings to vendor liaison.', 'Similar skills and qualities as the Vendor Liaison.', 235, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('28b8c9d3-809a-42bd-bbdd-aba29fc74507', '11111111-0000-0000-0000-000000000003', 'Lighting Keyman', 'Oversees all aspects of stage and venue lighting for the Evening Gathering. Works closely with venue liaison to procure or rent additional lighting, if stage and auditorium lighting is not adequate for performances. Responsible for vetting volunteers with lighting experience and theatre background. Assists installation in all on-site lighting and stage set up with a focus in lighting adjustments to cast and musicians. Works closely with performance coordinator and lighting crew to plan and execute lighting elements throughout the performance.', '', 236, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('8b63889e-2d59-4f96-ab6a-b771b4a507ee', '11111111-0000-0000-0000-000000000003', 'Accounting Keyman', 'Oversees all Accounting volunteers if an Assembly Hall is used. Works closely with the evening gathering overseer and Assembly Hall overseer to ensure all branch policy is followed when collecting funds at the Evening Gathering. Keeps adequate records of all financial transactions in connection with the donated funds at the Evening Gathering.', '', 237, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('10fa6041-3dfa-4aa1-9d2a-40b261f0cc1f', '11111111-0000-0000-0000-000000000001', 'Hotel Coordinator Assitant #2 - Marriot DTC (400 Rooms)', 'Assists Hotel Coordinator.  This assignment may require being on call 24/7 while delegates are present in hotel.', 'These brothers are asked to stay at the delegate hotel and as such involves signifigant expense', 238, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('5eb9c3dd-7c84-48d5-952d-7dc735dd4224', '11111111-0000-0000-0000-000000000001', 'Airport Greeter Keyman', 'Responsible for all greeting related volunteers at his assigned terminal during his assigned shift. Works closely with the airport greeter captains to ensure that greeters adhere closely to any guidelines and restrictions set forth by airport officials. Ensures that all greeter training is reviewed and implemented by volunteers. Remains mindful to include children, the aged, and infirm in the greeting reception. Remains attentive to volunteer safety concerns, especially related to standing for long periods, hydration, and late hour concerns.', '', 239, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('0fb3d8b1-65e5-414c-9314-c3d9e844cc7e', '11111111-0000-0000-0000-000000000006', 'Seating Keyman (Stage - Spanish)', '', '', 240, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('8f4bd06f-db19-4f26-a678-27357fc3c1c0', '11111111-0000-0000-0000-000000000006', 'Seating Keyman (Stage)', '', '', 241, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('01842bfd-a6a1-4a99-8dcf-a475e052e22c', '11111111-0000-0000-0000-000000000006', 'Vehicle Parking Keyman (Rideshare)', '', '', 242, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('fe127aa3-71f7-40f1-b792-97ca8028e0c0', '11111111-0000-0000-0000-000000000004', 'Video Keyman (Inventory - Spanish)', '', '', 243, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('548ae429-3650-42cd-a535-79cf4ff511c5', '11111111-0000-0000-0000-000000000004', 'Video Keyman (Inventory)', '', '', 244, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('217fb9f1-674a-427b-b588-6d187ad0bcfc', '11111111-0000-0000-0000-000000000005', 'Airport Safety Coordinator', 'Works with assigned Hospitality or Convention department(s) to ensure Safety, Emergency, and Hydration Plans are in place. Ensures properly trained safety volunteers are available to each department. Ensures physical site inspections take place as needed. Oversees a team of volunteers on call for emergencies.', 'Liaison between Safety and Airport. Good communicator and organizer.', 245, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('a422232b-da65-4dc3-b1e5-1c4a98ec7c27', '11111111-0000-0000-0000-000000000003', 'Food Keyman- Encouragement Gathering', 'Works directly with food overseer to create a menu for all food and beverages served at the Encouragement Gathering. Works with SCC Contact and Branch Contact for the purchase and procurement of food being served at the Evening Gathering. Works closely with the safety keyman to ensure Food Safety Guidelines (A-124) are being followed.', '', 246, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('5ccafd93-33e9-466b-91d3-8a841a94daae', '11111111-0000-0000-0000-000000000003', 'Vendor Liaison', 'Works with contract representative if convention venue is providing box lunches onsite based upon the venue contract. Collaborates with Hospitality Committee and SCC regarding food vendors and assists in finalizing contracts as needed. Works with activities overseer and evening gathering overseer to select food vendors for branch sponsored tours and the Evening Gathering(s). Accompanies the food overseer and Hospitality Committee to inspect the vendor''s facility to ensure food preparation follows Food Safety Guidelines (A124). During the convention, assists the food overseer in all meetings with the vendor contact.', 'Must be an excellent communicator. Personable with the ability to build and maintain business relationships. Will need to determine the best possible food quality available within a defined budget.', 247, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('2a279c54-d892-437b-8e41-63f5a0ae0acd', '11111111-0000-0000-0000-000000000005', 'Personnel Coordinator', 'Ensures all departments have needed safety personnel with proper credentials. Assists VM scheduling safety keyman to ensure properly trained volunteers (nurses, paramedics, and EMTs) are available for needed assignments.', 'Coordinates with all hospitality departments to ensure they have the needed safety personnel. Good communicator and organizer.', 248, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('b233ce40-ba51-4d09-9b7a-91f39117b691', '11111111-0000-0000-0000-000000000006', 'Signs & Mobile Support Keyman (Garages & Lots)', '', '', 249, NULL, '2026-05-02T01:16:57.027347+00:00'),
