  ('6b70e5f9-9b1e-4b4d-ab27-ddbbb18383d0', '11111111-0000-0000-0000-000000000006', 'Seating Keyman (Baptism)', '', '', 263, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('f8fb3682-bf1f-468b-a3ff-7fa82d27a154', '11111111-0000-0000-0000-000000000003', 'First Aid Keyman', 'Oversees First Aid volunteers. Works closely with venue liaison and safety coordinator on First Aid Plan (if venue is rented). Compiles incident report (TO-5) for all incidents of serious illness or personal injury requiring medical attention beyond minor first aid.', '', 264, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('499cf660-91cd-4ff0-a019-20bebb3d04d1', '11111111-0000-0000-0000-000000000002', 'Signage Keyman (Event Floor)', '', '', 265, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('12810df3-194e-4f70-b698-102251a3fa1d', '11111111-0000-0000-0000-000000000002', 'Exterior Keyman (Sidewalks)', '', '', 266, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('cce03048-eaa3-41d1-80cd-65fe7432761c', '11111111-0000-0000-0000-000000000003', 'Venue Liaison / Facility Coordinator', 'Serves as the primary point of contact between venue and Hospitality Committee (if venues are rented). Ensures all terms of the contract at the venue are upheld (if venues are rented). Serves as the primary point of contact between Assembly Hall overseer and Hospitality Committee (if Assembly Hall is used). Works with safety keyman to ensure guest safety is maintained at the Evening Gathering. Works with cleaning keyman to implement the Assembly Hall cleaning plan (if Assembly Hall is used). Takes the lead in securing any permits needed for venue alteration or hospitality setup. Serves as the point of contact for First Aid, and ensures the operating plan meets all legal and organizational requirements.', 'Must be an excellent communicator. Should have the ability to build and maintain multiple business relationships simultaneously. May work with assembly hall organization or non-witness venue staff. May need to secure permits and will need to understand all facets of the evening gathering operating plan.', 267, NULL, '2026-05-02T01:16:57.027347+00:00'),
  ('e00645e5-41e3-46f2-b45e-98af0cdc2e0f', '11111111-0000-0000-0000-000000000006', 'Rooming Desk Keyman (Event Level)', '', '', 268, NULL, '2026-05-02T01:16:57.027347+00:00'),
